using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly HttpClient client;
    private readonly Uri baseAddress;

    private int status = 200;
    private string responseBody = "{}";

    private string? method;
    private string? path;
    private string? contentType;
    private string? requestBody;

    public HttpPaymentGatewayTests()
    {
        var probe = new TcpListener(IPAddress.Loopback, 0);
        probe.Start();
        var port = ((IPEndPoint)probe.LocalEndpoint).Port;
        probe.Stop();

        baseAddress = new Uri($"http://127.0.0.1:{port}/");
        listener.Prefixes.Add(baseAddress.AbsoluteUri);
        listener.Start();
        _ = Task.Run(ServeAsync);

        client = new HttpClient { BaseAddress = baseAddress };
    }

    private async Task ServeAsync()
    {
        while (listener.IsListening)
        {
            HttpListenerContext context;
            try { context = await listener.GetContextAsync(); }
            catch (Exception) { return; }

            method = context.Request.HttpMethod;
            path = context.Request.Url!.AbsolutePath;
            contentType = context.Request.ContentType;
            using (var reader = new StreamReader(context.Request.InputStream, Encoding.UTF8))
                requestBody = await reader.ReadToEndAsync();

            var bytes = Encoding.UTF8.GetBytes(responseBody);
            context.Response.StatusCode = status;
            context.Response.ContentType = "application/json";
            await context.Response.OutputStream.WriteAsync(bytes);
            context.Response.Close();
        }
    }

    private Task<AuthorizationOutcome> Authorize(Money? amount = null) =>
        new HttpPaymentGateway(client).AuthorizeAsync("ORD-7", amount ?? new Money(12.50m, "eur"), CancellationToken.None);

    [Fact]
    public async Task The_request_is_a_json_post_to_the_authorizations_endpoint_with_the_agreed_fields()
    {
        responseBody = """{"status":"approved"}""";

        await Authorize();

        Assert.Equal("POST", method);
        Assert.Equal("/v1/authorizations", path);
        Assert.StartsWith("application/json", contentType);
        using var json = JsonDocument.Parse(requestBody!);
        var root = json.RootElement;
        Assert.Equal(["amount", "currency", "reference"], root.EnumerateObject().Select(p => p.Name).Order().ToArray());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        responseBody = """{"status":"approved"}""";

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        responseBody = """{"status":"declined"}""";

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        responseBody = """{"id":"auth_1","status":"approved","risk":{"score":3}}""";

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_payment_the_provider_refuses_outright_is_declined()
    {
        status = 402;
        responseBody = """{"error":"card_refused"}""";

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_error_statuses_are_not_mistaken_for_a_decision(int errorStatus)
    {
        status = errorStatus;
        responseBody = """{"status":"approved"}""";

        var failure = await Assert.ThrowsAsync<HttpRequestException>(() => Authorize());
        Assert.Equal((HttpStatusCode)errorStatus, failure.StatusCode);
    }

    [Fact]
    public async Task An_answer_that_is_not_json_is_reported_as_a_failure()
    {
        responseBody = "<html>gateway error</html>";

        await Assert.ThrowsAnyAsync<JsonException>(() => Authorize());
    }

    public void Dispose()
    {
        client.Dispose();
        listener.Close();
    }
}
